var kw = Tama.Args.Get(args, "keyword", "").ToUpper();
var targetTitle = Tama.Args.Get(args, "target", "");
int srcLimit = Tama.Args.Get(args, "sourceLimit", 2);
Func<Document, int, List<object>> describe = (Document d, int lim) => {
  var vs = new FilteredElementCollector(d).OfClass(typeof(ViewSchedule)).Cast<ViewSchedule>()
    .Where(v => !v.IsTemplate && v.Name.ToUpper().Contains(kw)).Take(lim).ToList();
  return vs.Select(v => {
    var def = v.Definition;
    var fields = new List<object>();
    for (int i = 0; i < def.GetFieldCount(); i++) {
      var f = def.GetField(i);
      fields.Add(new { f.ColumnHeading, ft = f.FieldType.ToString(), pid = f.ParameterId.IntegerValue, f.IsHidden, calc = f.IsCalculatedField });
    }
    var filters = new List<object>();
    for (int i = 0; i < def.GetFilterCount(); i++) {
      var fl = def.GetFilter(i);
      var f = def.GetField(fl.FieldId);
      string val = fl.IsStringValue ? fl.GetStringValue() : fl.IsElementIdValue ? (d.GetElement(fl.GetElementIdValue())?.Name ?? fl.GetElementIdValue().IntegerValue.ToString()) : fl.IsDoubleValue ? fl.GetDoubleValue().ToString() : fl.IsIntegerValue ? fl.GetIntegerValue().ToString() : "";
      filters.Add(new { field = f.ColumnHeading, type = fl.FilterType.ToString(), val });
    }
    var body = v.GetTableData().GetSectionData(SectionType.Body);
    return (object)new { id = v.Id.IntegerValue, v.Name, rows = body.NumberOfRows, cols = body.NumberOfColumns, scheme = def.AreaSchemeId.IntegerValue > 0 ? d.GetElement(def.AreaSchemeId)?.Name : null, template = v.ViewTemplateId.IntegerValue > 0 ? d.GetElement(v.ViewTemplateId)?.Name : null, fields, filters };
  }).ToList();
};
Document target = null;
foreach (Document d in app.Documents) if (!d.IsLinked && d.Title == targetTitle) target = d;
object tInfo = null;
if (target != null) {
  var schemes = new FilteredElementCollector(target).OfClass(typeof(AreaScheme)).Select(e => e.Name).ToList();
  var levels = new FilteredElementCollector(target).OfClass(typeof(Level)).Select(e => e.Name).OrderBy(n => n).ToList();
  var areaCount = new FilteredElementCollector(target).OfCategory(BuiltInCategory.OST_Areas).WhereElementIsNotElementType().GetElementCount();
  tInfo = new { schemes, levels, areaCount, existing = describe(target, 50) };
}
